"""Structural conformance checker for campaign results (used by the fuzzer)."""
import base64, ipaddress, plistlib, struct, sys
sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace/deps')
from common import COLUMNS
from gen_targets import plan as plan_targets

STATES = ('inactive', 'alias', 'conflict', 'usable')
SERVICE_KEYS = {'id', 'internal_open', 'internal_closed', 'external_open', 'external_closed',
                'internal_only', 'protocol_errors'}
LEASE_KEYS = {'lease', 'state', 'conflicts', 'internal', 'external', 'unresolved', 'services'}

class ShapeError(AssertionError):
    pass

def _addr_list(values, label):
    if not isinstance(values, list):
        raise ShapeError('%s not a list' % label)
    ints = []
    for item in values:
        if not isinstance(item, str):
            raise ShapeError('%s entry not a string: %r' % (label, item))
        parsed = ipaddress.IPv6Address(item)
        if str(parsed) != item:
            raise ShapeError('%s not compressed lowercase: %r' % (label, item))
        ints.append(int(parsed))
    if ints != sorted(set(ints)):
        raise ShapeError('%s not distinct/increasing' % label)
    return ints

def check_shape(job, res):
    if set(res) != {'manifest', 'rejected', 'snapshots', 'active_requests', 'plan'}:
        raise ShapeError('result keys %s' % sorted(res))
    ctx_leases = {l['id']: l for l in job['leases']}
    services = sorted(s['id'] for s in job['services'])
    kinds = {s['id']: s['kind'] for s in job['services']}
    queries = sorted(job['queries'])
    # manifest
    low_sets = {}
    expected_manifest = []
    ctx = {lid: {**row, 'network': ipaddress.IPv6Network(row['prefix']), 'subnets': sorted(row['subnets'])}
           for lid, row in ctx_leases.items()}
    manifest, lookup, lows = plan_targets(ctx, job['seed'])
    if res['manifest'] != manifest:
        raise ShapeError('manifest mismatch')
    for lid, targets in lows.items():
        low_sets[lid] = set(targets)
    # rejected
    previous = (-1, -1)
    for entry in res['rejected']:
        if not (isinstance(entry, list) and len(entry) == 2 and
                all(type(x) is int and x >= 0 for x in entry)):
            raise ShapeError('rejected entry %r' % (entry,))
        if tuple(entry) <= previous:
            raise ShapeError('rejected out of order %r after %r' % (entry, previous))
        previous = tuple(entry)
        if entry[0] >= len(job['captures']):
            raise ShapeError('rejected capture index out of range')
    # snapshots
    if len(res['snapshots']) != len(queries):
        raise ShapeError('snapshot count')
    for index, snap in enumerate(res['snapshots']):
        if set(snap) != {'at', 'ledger', 'unbound_applications', 'leases'}:
            raise ShapeError('snapshot keys')
        if snap['at'] != queries[index]:
            raise ShapeError('snapshot order')
        if set(snap['ledger']) != {'live', 'deleted', 'conflict'}:
            raise ShapeError('ledger keys')
        if not all(type(v) is int and v >= 0 for v in snap['ledger'].values()):
            raise ShapeError('ledger values')
        if type(snap['unbound_applications']) is not int or snap['unbound_applications'] < 0:
            raise ShapeError('unbound_applications')
        if [row['lease'] for row in snap['leases']] != sorted(ctx_leases):
            raise ShapeError('lease order/coverage')
        for report in snap['leases']:
            if set(report) != LEASE_KEYS:
                raise ShapeError('lease report keys')
            lid = report['lease']
            row = ctx_leases[lid]
            if report['state'] not in STATES:
                raise ShapeError('state value')
            conflicts = _addr_list(report['conflicts'], 'conflicts')
            internal = _addr_list(report['internal'], 'internal')
            external = _addr_list(report['external'], 'external')
            unresolved = _addr_list(report['unresolved'], 'unresolved')
            active = row['start'] <= snap['at'] < row['end']
            if not active:
                if report['state'] != 'inactive' or conflicts or internal or external or unresolved:
                    raise ShapeError('inactive lease must be empty: %r' % (report,))
            else:
                if report['state'] == 'inactive':
                    raise ShapeError('active lease reported inactive')
                if report['state'] == 'conflict' and not conflicts:
                    raise ShapeError('conflict state without conflicts')
                if report['state'] == 'usable' and conflicts:
                    raise ShapeError('usable state with conflicts')
                if report['state'] != 'usable' and (internal or external):
                    raise ShapeError('quarantined lease exposes clean roles')
                if set(internal) & set(external):
                    raise ShapeError('clean roles overlap')
                want = sorted(low_sets[lid] - set(internal) - set(external))
                if unresolved != want:
                    raise ShapeError('unresolved mismatch for %s' % lid)
                if set(conflicts) - set(low_sets[lid]) and False:
                    pass
            if [s['id'] for s in report['services']] != services:
                raise ShapeError('service order/coverage for %s' % lid)
            for svc in report['services']:
                if set(svc) != SERVICE_KEYS:
                    raise ShapeError('service keys')
                io = _addr_list(svc['internal_open'], 'internal_open')
                ic = _addr_list(svc['internal_closed'], 'internal_closed')
                eo = _addr_list(svc['external_open'], 'external_open')
                ec = _addr_list(svc['external_closed'], 'external_closed')
                only = _addr_list(svc['internal_only'], 'internal_only')
                if type(svc['protocol_errors']) is not int or svc['protocol_errors'] < 0:
                    raise ShapeError('protocol_errors')
                if set(io) & set(ic) or set(eo) & set(ec):
                    raise ShapeError('open/closed overlap')
                if not set(io) <= set(internal) or not set(ic) <= set(internal):
                    raise ShapeError('internal subsets')
                if not set(eo) <= set(external) or not set(ec) <= set(external):
                    raise ShapeError('external subsets')
                want_only = io if (external and set(ec) == set(external)) else []
                if only != want_only:
                    raise ShapeError('internal_only rule')
    # active_requests
    names = sorted(r['id'] for r in job['requests'])
    if [row['id'] for row in res['active_requests']] != names:
        raise ShapeError('active_requests coverage/order')
    for entry in res['active_requests']:
        if set(entry) != {'id', 'active'} or type(entry['active']) is not bool:
            raise ShapeError('active_requests entry %r' % (entry,))
    # plan
    plan = res['plan']
    if set(plan) != {'resolved', 'cost', 'assignments'}:
        raise ShapeError('plan keys')
    if plan['resolved'] != len(plan['assignments']):
        raise ShapeError('resolved != len(assignments)')
    requests = {r['id']: r for r in job['requests']}
    offers = {o['id']: o for o in job['offers']}
    active = {row['id']: row['active'] for row in res['active_requests']}
    listed = [row['request'] for row in plan['assignments']]
    if listed != sorted(listed) or len(set(listed)) != len(listed):
        raise ShapeError('assignment order/reuse')
    total = 0
    used_offer = {}
    used_rq = {}
    used_oq = {}
    rq = {n['id']: n for n in job['request_quotas']}
    oq = {n['id']: n for n in job['offer_quotas']}
    def path(nodes, name):
        out = []
        while name is not None:
            out.append(name)
            name = nodes[name]['parent']
        return out
    for entry in plan['assignments']:
        if set(entry) != {'request', 'offer', 'send', 'finish'}:
            raise ShapeError('assignment keys')
        rid = entry['request']; oid = entry['offer']
        if rid not in requests or oid not in offers:
            raise ShapeError('unknown assignment reference')
        request = requests[rid]; offer = offers[oid]
        if not active[rid]:
            raise ShapeError('inactive request assigned')
        if rid not in offer['requests'] or request['service'] != offer['service']:
            raise ShapeError('assignment predicate')
        if not (request['at'] <= offer['time'] < ctx_leases[request['lease']]['end']):
            raise ShapeError('assignment window')
        net = ipaddress.IPv6Network(offer['prefix'], strict=True)
        if not (int(net.network_address) <= int(ipaddress.IPv6Address(request['target']))
                <= int(net.broadcast_address)):
            raise ShapeError('assignment prefix')
        used_offer[oid] = used_offer.get(oid, 0) + 1
        if used_offer[oid] > offer['capacity']:
            raise ShapeError('offer capacity')
        for node in path(rq, request['group']):
            used_rq[node] = used_rq.get(node, 0) + 1
        for node in path(oq, offer['group']):
            used_oq[node] = used_oq.get(node, 0) + 1
        total += offer['cost']
        check_certificate(kinds[request['service']], entry['send'], entry['finish'])
    for node, used in used_rq.items():
        if used > rq[node]['capacity']:
            raise ShapeError('request quota %s' % node)
    for node, used in used_oq.items():
        if used > oq[node]['capacity']:
            raise ShapeError('offer quota %s' % node)
    if total != plan['cost'] or type(plan['cost']) is not int:
        raise ShapeError('plan cost')
    return True

def check_certificate(kind, send, finish):
    if kind == 'tcp':
        if send != [] or finish != []:
            raise ShapeError('tcp certificate')
        return
    if kind == 'adb':
        if len(send) != 1 or len(finish) != 1:
            raise ShapeError('adb certificate length')
        pkt = base64.b64decode(send[0], validate=True)
        cmd, a0, a1, ln, ck, mg = struct.unpack('<6I', pkt[:24])
        if (cmd, a0, a1) != (0x4e584e43, 0x01000000, 4096):
            raise ShapeError('adb connect header')
        if pkt[24:] != b'host::zgrab2' or ln != 12 or mg != cmd ^ 0xffffffff:
            raise ShapeError('adb connect body')
        if ck != (sum(pkt[24:]) & 0xffffffff):
            raise ShapeError('adb checksum')
        fin = base64.b64decode(finish[0], validate=True)
        cmd2, b0, b1, ln2, ck2, mg2 = struct.unpack('<6I', fin[:24])
        if (cmd2, b0, b1, ln2, ck2, mg2) != (0x45534c43, 0, 0, 0, 0, 0x45534c43 ^ 0xffffffff):
            raise ShapeError('adb close')
        if len(fin) != 24:
            raise ShapeError('adb close length')
        return
    if kind == 'sync':
        if finish != [] or len(send) != 2:
            raise ShapeError('sync certificate length')
        keys = ['ProductVersion', 'ProductName']
        for index, blob in enumerate(send):
            raw = base64.b64decode(blob, validate=True)
            size = struct.unpack('>I', raw[:4])[0]
            if not (1 <= size <= 65532) or len(raw) != 4 + size:
                raise ShapeError('sync frame length')
            value = plistlib.loads(raw[4:])
            if value != {'Key': keys[index], 'Label': 'usbmuxd', 'ProtocolVersion': '2',
                         'Request': 'GetValue'}:
                raise ShapeError('sync plist %r' % (value,))
            if not all(type(v) is str for v in value.values()):
                raise ShapeError('sync plist types')
        return
    raise ShapeError('unknown kind %s' % kind)
